const F1=0x40022000,F4=0x40023c00,KEY1=0x45670123,KEY2=0xcdef89ab;
const part=(value,a,n)=>n===4?value>>>0:(value>>>((a&3)*8))&(n===1?255:65535);
function hash(text){let h=2166136261;for(const c of text)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0;}

// Documented STM32F1/F4 embedded-Flash controller, option state and device signatures.
export class STMFlash {
 constructor(r){this.r=r;this.f4=r.board.cpu==='cortex-m4f';this.base=this.f4?F4:F1;const h=hash(r.board.mcu);this.uid=new Uint8Array(12);const view=new DataView(this.uid.buffer);view.setUint32(0,0x002d001f^(h>>>16),true);view.setUint32(4,0x33304713^h,true);view.setUint32(8,0x51000000^Math.imul(h,0x9e3779b1),true);this.option=new Uint8Array([0xa5,0x5a,0xff,0x00,0xff,0x00,0xff,0x00,0xff,0x00,0xff,0x00,0xff,0x00,0xff,0x00]);this.reset();}
 reset(){this.keyStage=0;this.optKeyStage=0;this.locked=true;this.optionLocked=true;this.acr=this.f4?0:0x30;this.cr=this.f4?0x80000000:0x80;this.address=0;this.optcr=this.f4?0x0fffaaed:0;}
 systemReset(){this.reset();}
 signature(a,n){let bytes,start;if(this.f4&&a>=0x1fff7a10&&a+n<=0x1fff7a1c){bytes=this.uid;start=0x1fff7a10;}else if(!this.f4&&a>=0x1ffff7e8&&a+n<=0x1ffff7f4){bytes=this.uid;start=0x1ffff7e8;}else if(this.f4&&a>=0x1fff7a22&&a+n<=0x1fff7a24){bytes=new Uint8Array(new Uint16Array([this.r.board.flashSize/1024]).buffer);start=0x1fff7a22;}else if(!this.f4&&a>=0x1ffff7e0&&a+n<=0x1ffff7e2){bytes=new Uint8Array(new Uint16Array([this.r.board.flashSize/1024]).buffer);start=0x1ffff7e0;}else if(!this.f4&&a>=0x1ffff800&&a+n<=0x1ffff810){bytes=this.option;start=0x1ffff800;}else return undefined;let v=0;for(let i=0;i<n;i++)v|=bytes[a-start+i]<<(8*i);return v>>>0;}
 rawStatus(){return this.r.cpu&&this.r.exports.flash_status?this.r.exports.flash_status(this.r.cpu):0;}
 status(){const s=this.rawStatus();return this.f4?((s&4?1:0)|(s&1?128:0)|(s&2?32:0)):((s&4?32:0)|(s&1?4:0)|(s&2?4:0));}
 clearStatus(v){let mask=0;if(this.f4){if(v&1)mask|=4;if(v&(2|16|32|64|128))mask|=3;}else{if(v&32)mask|=4;if(v&(4|16))mask|=3;}this.r.exports.flash_clear_status(this.r.cpu,mask);}
 read(a,n=4){const sig=this.signature(a,n);if(sig!==undefined)return sig;const x=a&~3;if(x<this.base||x>this.base+(this.f4?20:32))return undefined;let v=0;if(x===this.base)v=this.acr;else if(x===this.base+12)v=this.status();else if(x===this.base+16)v=this.cr;else if(!this.f4&&x===this.base+20)v=this.address;else if(!this.f4&&x===this.base+28)v=this.option[0]|this.option[2]<<10|this.option[4]<<18|this.option[6]<<26;else if(!this.f4&&x===this.base+32)v=0xffffffff;else if(this.f4&&x===this.base+20)v=this.optcr;return part(v,a,n);}
 unlock(value,option=false){value>>>=0;const field=option?'optKeyStage':'keyStage';if(this[field]===0&&value===KEY1)this[field]=1;else if(this[field]===1&&value===KEY2){this[field]=0;if(option){this.optionLocked=false;if(this.f4)this.optcr&=~1;}else{this.locked=false;this.cr&=~(this.f4?0x80000000:0x80);}}else this[field]=0;}
 setWidth(){let width=0;if(!this.locked&&(this.cr&1))width=this.f4?[1,2,4,8][(this.cr>>>8)&3]:2;this.r.exports.flash_program_width(this.r.cpu,width);}
 eraseF1(){if(this.locked)return;if(this.cr&4)this.r.exports.flash_erase(this.r.cpu,0,this.r.board.flashSize);else if(this.cr&2){const offset=this.address-0x08000000;if(offset>=0&&offset<this.r.board.flashSize)this.r.exports.flash_erase(this.r.cpu,offset-offset%1024,1024);}}
 sector(index){if(index<4)return [index*16384,16384];if(index===4)return [65536,65536];return [131072+(index-5)*131072,131072];}
 eraseF4(){if(this.locked)return;if(this.cr&4)this.r.exports.flash_erase(this.r.cpu,0,this.r.board.flashSize);else if(this.cr&2){const [start,length]=this.sector((this.cr>>>3)&15);if(start<this.r.board.flashSize)this.r.exports.flash_erase(this.r.cpu,start,Math.min(length,this.r.board.flashSize-start));}}
 writeOption(a,v,n){if(this.f4||a<0x1ffff800||a+n>0x1ffff810)return false;if(this.optionLocked||!(this.cr&16))return true;for(let i=0;i<n;i++)this.option[a-0x1ffff800+i]&=v>>>(8*i)&255;return true;}
 write(a,v,n=4){if(this.writeOption(a,v,n))return true;const x=a&~3;if(x<this.base||x>this.base+(this.f4?20:32))return false;if(n!==4||a!==x)throw Error('STM32 FLASH register erişimi 32-bit hizalı olmalı.');if(x===this.base){this.acr=v>>>0;return true;}if(x===this.base+4){this.unlock(v);return true;}if(x===this.base+8){this.unlock(v,true);return true;}if(x===this.base+12){this.clearStatus(v);return true;}if(!this.f4&&x===this.base+20){this.address=v>>>0;return true;}if(this.f4&&x===this.base+20){if(!(this.optcr&1)){this.optcr=v>>>0;if(v&1)this.optionLocked=true;}return true;}if(x===this.base+16){if(this.locked&&!(v&(this.f4?0x80000000:0x80)))return true;this.cr=v>>>0;if(v&(this.f4?0x80000000:0x80))this.locked=true;if(v&(this.f4?0x10000:0x40))(this.f4?this.eraseF4():this.eraseF1());this.setWidth();return true;}return true;}
}
